package com.oms.order.service;

import org.springframework.stereotype.Service;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import javax.annotation.Resource;
import java.util.*;
import static com.oms.order.service.OrderValues.*;

@Service
public class OrderAutoReviewService {
    @Resource private OrderRepository repository;
    @Resource private OrderCatalog catalog;
    private TransactionTemplate tx(){return new TransactionTemplate(new DataSourceTransactionManager(repository.db().getDataSource()));}
    @SuppressWarnings("unchecked") private static Map<String,Object> policy(Object json){try{return OrderAutoReviewPolicy.validate(JSON.readValue(String.valueOf(json),Map.class));}catch(Exception e){throw new IllegalArgumentException("审单规则损坏，请重新保存；本次不会自动放行");}}
    public List<Map<String,Object>> configurations(String company){List<Map<String,Object>> rows=repository.db().query("SELECT c.channel_id,c.channel_name,r.policy_json,r.revision FROM oms_order_pull_config c LEFT JOIN oms_order_review_config r ON r.company_code=c.company_code AND r.channel_id=c.channel_id WHERE c.company_code=? ORDER BY c.channel_id",ROW,company);for(Map<String,Object> row:rows){Object json=row.remove("policy_json");row.put("configured",json!=null);row.put("policy",json==null?OrderAutoReviewPolicy.defaults():policy(json));if(row.get("revision")==null)row.put("revision",0);}return rows;}
    public Map<String,Object> configuration(String company,long channel){require(repository.db().queryForObject("SELECT COUNT(*) FROM oms_order_pull_config WHERE company_code=? AND channel_id=?",Long.class,company,channel)==1,"店铺未接入或无权访问");List<Map<String,Object>> rows=repository.db().query("SELECT policy_json,revision FROM oms_order_review_config WHERE company_code=? AND channel_id=?",ROW,company,channel);Map<String,Object> result=new LinkedHashMap<>();result.put("channel_id",channel);result.put("revision",rows.isEmpty()?0:rows.get(0).get("revision"));result.put("policy",rows.isEmpty()?OrderAutoReviewPolicy.defaults():policy(rows.get(0).get("policy_json")));return result;}
    @SuppressWarnings("unchecked") public void save(String company,Map<String,Object> input,String actor){
        long channel=number(input,"channel_id");catalog.validateShop(company,channel);require(input.get("policy") instanceof Map,"请填写审单规则");Map<String,Object> p=OrderAutoReviewPolicy.validate((Map<String,Object>)input.get("policy"));
        List<String> skus=(List<String>)p.get("review_skus");if(!skus.isEmpty()){Map<String,List<Map<String,Object>>> goods=catalog.goods(company,skus);for(String sku:skus)require(goods.getOrDefault(sku,Collections.emptyList()).size()==1,"复核SKU不存在或不唯一："+sku);}
        tx().execute(status->{List<Map<String,Object>> shops=repository.db().query("SELECT lease_until FROM oms_order_pull_config WHERE company_code=? AND channel_id=? FOR UPDATE",ROW,company,channel);require(shops.size()==1,"店铺未接入或无权访问");require(shops.get(0).get("lease_until")==null||time(text(shops.get(0),"lease_until")).isBefore(java.time.LocalDateTime.now()),"店铺任务正在处理，请稍后修改规则");List<Map<String,Object>> old=repository.db().query("SELECT revision FROM oms_order_review_config WHERE company_code=? AND channel_id=? FOR UPDATE",ROW,company,channel);require((old.isEmpty()?0:number(old.get(0),"revision"))==number(input,"revision"),"审单规则已变化，请刷新后重试");repository.db().update("INSERT INTO oms_order_review_config(company_code,channel_id,policy_json,updated_by) VALUES (?,?,?,?) ON DUPLICATE KEY UPDATE policy_json=VALUES(policy_json),updated_by=VALUES(updated_by),revision=revision+1",company,channel,encode(p),actor);return null;});
    }
    private static Map<String,Object> facts(OrderRepository repo,String company,long id){
        JdbcTemplate db=repo.db();List<Map<String,Object>> found=db.query("SELECT o.gift_block_reason,o.id,o.status,o.payment,o.stock_error,o.review_status,o.review_decision,o.review_snapshot,o.control_version,o.channel_id,o.platform_order_id,p.business_order_id,p.conversion_status,p.refund_block_reason,p.exchange_block_reason,p.change_pending,p.platform_status,p.fulfillment_block_reason,p.processing_hash,(SELECT COALESCE(SUM(sl.shipped_quantity),0) FROM oms_order_shipment_line sl JOIN oms_order_shipment sh ON sh.company_code=sl.company_code AND sh.id=sl.shipment_id WHERE sh.company_code=o.company_code AND sh.order_id=o.id AND sh.business_type='SALE') shipped_quantity FROM oms_order o JOIN oms_platform_order p ON p.company_code=o.company_code AND p.id=o.platform_order_id WHERE o.company_code=? AND o.id=?",ROW,company,id);require(found.size()==1,"业务订单不存在或无权访问");Map<String,Object> o=found.get(0);List<Map<String,Object>> lines=db.query("SELECT l.sku_sn,(l.quantity-l.cancelled_quantity) quantity,l.reserved_quantity,l.inventory_reason_code,IF(pl.manual_sku_sn IS NULL OR pl.manual_sku_sn='',0,1) manual_match FROM oms_order_line l LEFT JOIN oms_platform_order_line pl ON pl.company_code=l.company_code AND pl.platform_order_id=? AND pl.platform_oid=l.platform_oid WHERE l.company_code=? AND l.order_id=? AND l.business_type='SALE' AND l.quantity>l.cancelled_quantity ORDER BY l.id",ROW,o.get("platform_order_id"),company,id);
        long quantity=0,reserved=0,manual=0,invalid=0,ledger=0;Set<String> skus=new LinkedHashSet<>();for(Map<String,Object> l:lines){quantity=Math.addExact(quantity,number(l,"quantity"));reserved=Math.addExact(reserved,number(l,"reserved_quantity"));manual+=number(l,"manual_match");if(text(l,"sku_sn").isEmpty()||number(l,"quantity")<=0||number(l,"reserved_quantity")<0||number(l,"reserved_quantity")>number(l,"quantity"))invalid++;if("BALANCE_MISMATCH".equals(text(l,"inventory_reason_code")))ledger++;skus.add(text(l,"sku_sn"));}o.put("quantity",quantity);o.put("reserved_quantity",reserved);o.put("manual_match_count",manual);o.put("invalid_lines",invalid);o.put("ledger_errors",ledger);o.put("skus",new ArrayList<>(skus));return o;
    }
    private static Map<String,Object> assessment(OrderRepository repo,String company,Map<String,Object> o){
        List<Map<String,Object>> configs=repo.db().query("SELECT policy_json,revision FROM oms_order_review_config WHERE company_code=? AND channel_id=?",ROW,company,o.get("channel_id"));
        Map<String,Object> f=new LinkedHashMap<>();for(String key:Arrays.asList("id","status","payment","stock_error","business_order_id","conversion_status","refund_block_reason","exchange_block_reason","change_pending","platform_status","fulfillment_block_reason","processing_hash","quantity","reserved_quantity","shipped_quantity","manual_match_count","invalid_lines","ledger_errors","skus"))f.put(key,"payment".equals(key)?text(o,key):o.get(key));
        Map<String,Object> result=OrderAutoReviewPolicy.assess(configs.isEmpty()?OrderAutoReviewPolicy.defaults():policy(configs.get(0).get("policy_json")),f);result.put("rule_revision",configs.isEmpty()?0:configs.get(0).get("revision"));return result;
    }
    /** Caller holds shop, platform and parent locks. Pure local reads/writes share the caller transaction. */
    static void evaluate(OrderRepository repo,String company,long id,boolean explicit,String actor){
        Map<String,Object> o=facts(repo,company,id);if("APPROVED".equals(text(o,"review_status")))return;
        if(!explicit&&!Arrays.asList("UNASSESSED","WAIT_STOCK","BLOCKED").contains(text(o,"review_decision")))return;
        Map<String,Object> result=assessment(repo,company,o);String decision=text(result,"decision"),summary=text(result,"summary");if(summary.length()>200)summary=summary.substring(0,200);
        String snapshot=encode(result);try{if(!text(o,"review_snapshot").isEmpty()&&com.oms.common.util.AllocationDigest.hash(result).equals(com.oms.common.util.AllocationDigest.hash(JSON.readValue(text(o,"review_snapshot"),Map.class))))return;}catch(Exception ignored){}
        boolean approved="AUTO_APPROVED".equals(decision);
        repo.db().update("UPDATE oms_order SET review_status=?,review_decision=?,review_policy=?,review_by=?,review_at=IF(?=1,NOW(),NULL),review_reason=?,review_snapshot=?,review_evaluated_at=NOW(),control_version=control_version+1 WHERE company_code=? AND id=?",approved?"APPROVED":"PENDING",decision,"MANUAL_REQUIRED".equals(decision)&&number((Map<String,Object>)result.get("facts"),"manual_match_count")>0&&number((Map<String,Object>)result.get("policy"),"manual_match_required")==1?"MANUAL_MATCH":text((Map<String,Object>)result.get("policy"),"mode"),approved?"系统":"",approved?1:0,summary,snapshot,company,id);
        repo.db().update("INSERT INTO oms_order_review_event(company_code,order_id,action,decision,assessment,operator_name) VALUES (?,?,?,?,?,?)",company,id,explicit?"RECHECK":"AUTO_REVIEW",decision,snapshot,actor);
        repo.log(company,number(o,"platform_order_id"),approved?"REVIEW_AUTO":"REVIEW_PENDING",approved?"SUCCESS":decision,summary,actor);
        if(approved)repo.autoAllocationChanged(company,id,"自动审核通过");
    }
    public Map<String,Object> preview(String company,long id){Map<String,Object> o=facts(repository,company,id);Map<String,Object> result=assessment(repository,company,o);result.put("control_version",o.get("control_version"));result.put("read_only",true);return result;}
    public void recheck(String company,long id,long version,String actor){tx().execute(status->{
        Map<String,Object> initial=facts(repository,company,id);List<Map<String,Object>> shops=repository.db().query("SELECT lease_until FROM oms_order_pull_config WHERE company_code=? AND channel_id=? FOR UPDATE",ROW,company,initial.get("channel_id"));require(shops.size()==1&&(shops.get(0).get("lease_until")==null||time(text(shops.get(0),"lease_until")).isBefore(java.time.LocalDateTime.now())),"店铺正在处理，请稍后重新判定");repository.db().queryForList("SELECT id FROM oms_platform_order WHERE company_code=? AND id=? FOR UPDATE",company,initial.get("platform_order_id"));Map<String,Object> o=repository.db().query("SELECT * FROM oms_order WHERE company_code=? AND id=? FOR UPDATE",ROW,company,id).get(0);require(number(o,"control_version")==version,"订单已变化，请刷新后重试");require("PENDING".equals(text(o,"review_status"))&&"WAIT_ALLOCATION".equals(text(o,"status")),"仅待审核且未停止履约的订单可重新判定");OrderReviewPolicy.requireRemaining(repository,company,id);evaluate(repository,company,id,true,actor);return null;
    });}
    public static void attachDetail(OrderRepository repo,String company,Map<String,Object> order){Object snapshot=order.remove("review_snapshot");if(snapshot!=null)try{order.put("review_assessment",JSON.readValue(snapshot.toString(),Map.class));}catch(Exception e){order.put("review_assessment_error","审核依据无法读取，请人工核对");}List<Map<String,Object>> events=repo.db().query("SELECT action,decision,assessment,operator_name,create_time FROM oms_order_review_event WHERE company_code=? AND order_id=? ORDER BY id DESC LIMIT 20",ROW,company,order.get("id"));for(Map<String,Object> event:events){Object body=event.remove("assessment");try{event.put("assessment",JSON.readValue(body.toString(),Map.class));}catch(Exception ignored){}}order.put("review_events",events);}
}
